29	function formatDuration(minutes: number): string {
30	  if (minutes < 60) return `${minutes}min`;
31	  const hours = Math.floor(minutes / 60);
32	  const mins = minutes % 60;
33	  return mins > 0 ? `${hours}h ${mins}min` : `${hours}h`;
34	}
