42	export function UsersTab() {
43	  const { users, getUserDetail } = useAdminUsers();
44	  const [search, setSearch] = useState('');
45	  const [roleFilter, setRoleFilter] = useState('all');
46	  const [statusFilter, setStatusFilter] = useState('all');
47	  const [expandedUser, setExpandedUser] = useState<string | null>(null);
48	  const [userDetails, setUserDetails] = useState<Record<string, UserDetail>>({});
49	  const [loadingDetail, setLoadingDetail] = useState<string | null>(null);
50	
51	  const handleExpand = useCallback(
52	    async (userId: string) => {
53	      if (expandedUser === userId) {
54	        setExpandedUser(null);
55	        return;
56	      }
57	      setExpandedUser(userId);
58	      if (!userDetails[userId]) {
59	        setLoadingDetail(userId);
60	        try {
61	          const detail = await getUserDetail(userId);
62	          setUserDetails((prev) => ({ ...prev, [userId]: detail }));
63	        } catch {
64	          // Silently handle
65	        } finally {
66	          setLoadingDetail(null);
67	        }
68	      }
69	    },
70	    [expandedUser, userDetails, getUserDetail]
71	  );
72	
73	  const allUsers = users.data || [];
74	
75	  // Get unique roles for filter
76	  const roles = [...new Set(allUsers.map((u) => u.role_display_name).filter(Boolean))] as string[];
77	
78	  // Apply filters
79	  const filteredUsers = allUsers.filter((u) => {
80	    if (search) {
81	      const s = search.toLowerCase();
82	      if (!u.nome.toLowerCase().includes(s) && !u.username.toLowerCase().includes(s)) {
83	        return false;
84	      }
85	    }
86	    if (roleFilter !== 'all' && u.role_display_name !== roleFilter) return false;
87	    if (statusFilter === 'online' && !u.isOnline) return false;
88	    if (statusFilter === 'offline' && u.isOnline) return false;
89	    return true;
90	  });
91	
92	  return (
93	    <div className="space-y-4">
94	      {/* Filters */}
95	      <Card className="rounded-2xl border-border/50">
96	        <CardContent className="p-4">
97	          <div className="flex flex-col sm:flex-row gap-3">
98	            <div className="relative flex-1">
99	              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
100	              <Input data-mia-field="search"
101	                placeholder="Buscar por nome ou username..."
102	                value={search}
103	                onChange={(e) => setSearch(e.target.value)}
104	                className="pl-9 rounded-xl"
105	              />
106	            </div>
107	            <Select value={roleFilter} onValueChange={setRoleFilter}>
108	              <SelectTrigger data-mia-filter="role_filter" className="w-[180px] rounded-xl">
109	                <SelectValue placeholder="Role" />
110	              </SelectTrigger>
111	              <SelectContent>
112	                <SelectItem value="all">Todos os Roles</SelectItem>
113	                {roles.map((r) => (
114	                  <SelectItem key={r} value={r}>
115	                    {r}
116	                  </SelectItem>
117	                ))}
118	              </SelectContent>
119	            </Select>
120	            <Select value={statusFilter} onValueChange={setStatusFilter}>
121	              <SelectTrigger data-mia-filter="status_filter" className="w-[140px] rounded-xl">
122	                <SelectValue placeholder="Status" />
123	              </SelectTrigger>
124	              <SelectContent>
125	                <SelectItem value="all">Todos</SelectItem>
126	                <SelectItem value="online">Online</SelectItem>
127	                <SelectItem value="offline">Offline</SelectItem>
128	              </SelectContent>
129	            </Select>
130	          </div>
131	        </CardContent>
132	      </Card>
133	
134	      {/* Users List */}
135	      <Card className="rounded-2xl border-border/50">
136	        <CardHeader className="pb-3">
137	          <CardTitle className="text-sm font-semibold flex items-center gap-2">
138	            <Users className="h-4 w-4 text-[#57715B]" />
139	            Usuarios
140	            <Badge variant="secondary" className="ml-2 font-mono">
141	              {filteredUsers.length}
142	            </Badge>
143	          </CardTitle>
144	        </CardHeader>
145	        <CardContent className="p-0">
146	          {users.isLoading ? (
147	            <div className="flex items-center justify-center py-12 text-muted-foreground text-sm">
148	              Carregando usuarios...
149	            </div>
150	          ) : filteredUsers.length === 0 ? (
151	            <div className="flex flex-col items-center justify-center py-12 text-muted-foreground gap-2">
152	              <Users className="h-10 w-10 opacity-30" />
153	              <p className="text-sm">Nenhum usuario encontrado</p>
154	            </div>
155	          ) : (
156	            <ScrollArea className="max-h-[700px]">
157	              <div className="divide-y divide-border/50">
158	                {filteredUsers.map((u) => {
159	                  const isExpanded = expandedUser === u.user_id;
160	                  const detail = userDetails[u.user_id];
161	                  const isLoadingThis = loadingDetail === u.user_id;
162	
163	                  return (
164	                    <div key={u.user_id}>
165	                      <button
166	                        className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-muted/50 transition-colors"
167	                        onClick={() => handleExpand(u.user_id)}
168	                      >
169	                        {/* Status */}
170	                        <span
171	                          className={`h-2.5 w-2.5 rounded-full shrink-0 ${
172	                            u.isOnline ? 'bg-green-500' : 'bg-gray-300'
173	                          }`}
174	                        />
175	
176	                        {/* Name + Role */}
177	                        <div className="flex-1 min-w-0">
178	                          <p className="font-medium text-sm truncate">{u.nome}</p>
179	                          <p className="text-xs text-muted-foreground">
180	                            {u.role_display_name || 'Sem role'}
181	                          </p>
182	                        </div>
183	
184	                        {/* Stats */}
185	                        <div className="hidden sm:flex items-center gap-4 text-xs text-muted-foreground">
186	                          <span className="flex items-center gap-1" title="Sessoes">
187	                            <Clock className="h-3 w-3" />
188	                            {u.sessionCount}
189	                          </span>
190	                          <span className="flex items-center gap-1" title="Page Views">
191	                            <Eye className="h-3 w-3" />
192	                            {u.pageViews}
193	                          </span>
194	                          <span className="flex items-center gap-1" title="Tempo Total">
195	                            <BarChart3 className="h-3 w-3" />
196	                            {formatDuration(u.totalMinutes)}
197	                          </span>
198	                        </div>
199	
200	                        {/* Last session */}
201	                        <div className="hidden md:block text-xs text-muted-foreground text-right min-w-[90px]">
202	                          {u.lastSession
203	                            ? formatDistanceToNow(new Date(u.lastSession), {
204	                                addSuffix: true,
205	                                locale: ptBR,
206	                              })
207	                            : 'Nunca'}
208	                        </div>
209	
210	                        {/* Expand icon */}
211	                        {isExpanded ? (
212	                          <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
213	                        ) : (
214	                          <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
215	                        )}
216	                      </button>
217	
218	                      {/* Expanded Detail */}
219	                      {isExpanded && (
220	                        <div className="px-4 pb-4 bg-muted/30">
221	                          {isLoadingThis ? (
222	                            <p className="text-sm text-muted-foreground py-4">
223	                              Carregando detalhes...
224	                            </p>
225	                          ) : detail ? (
226	                            <UserDetailPanel user={u} detail={detail} />
227	                          ) : null}
228	                        </div>
229	                      )}
230	                    </div>
231	                  );
232	                })}
233	              </div>
234	            </ScrollArea>
235	          )}
236	        </CardContent>
237	      </Card>
238	    </div>
239	  );
240	}
241	
242	function UserDetailPanel({ user, detail }: { user: AdminUser; detail: UserDetail }) {
243	  return (
244	    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-3">
245	      {/* Top Pages */}
246	      <Card className="rounded-xl border-border/50">
247	        <CardHeader className="pb-2 px-3 pt-3">
248	          <CardTitle className="text-xs font-semibold text-muted-foreground">
249	            Top Paginas
250	          </CardTitle>
251	        </CardHeader>
252	        <CardContent className="px-3 pb-3">
253	          {detail.topPages.length === 0 ? (
254	            <p className="text-xs text-muted-foreground">Sem dados</p>
255	          ) : (
256	            <div className="space-y-1.5">
257	              {detail.topPages.map((p) => (
258	                <div key={p.route} className="flex items-center justify-between text-xs">
259	                  <span className="truncate text-foreground">{p.route}</span>
260	                  <Badge variant="secondary" className="ml-2 font-mono text-[10px]">
261	                    {p.count}
262	                  </Badge>
263	                </div>
264	              ))}
265	            </div>
266	          )}
267	        </CardContent>
268	      </Card>
269	
270	      {/* Recent Sessions */}
271	      <Card className="rounded-xl border-border/50">
272	        <CardHeader className="pb-2 px-3 pt-3">
273	          <CardTitle className="text-xs font-semibold text-muted-foreground">
274	            Sessoes Recentes
275	          </CardTitle>
276	        </CardHeader>
277	        <CardContent className="px-3 pb-3">
278	          <ScrollArea className="h-[150px]">
279	            <div className="space-y-1.5">
280	              {detail.recentSessions.map((s: any) => {
281	                const duration = Math.round(
282	                  (new Date(s.ended_at || s.last_activity).getTime() -
283	                    new Date(s.started_at).getTime()) /
284	                    60000
285	                );
286	                const DeviceIcon = DEVICE_ICONS[s.device_type] || Monitor;
287	
288	                return (
289	                  <div key={s.id} className="flex items-center gap-2 text-xs">
290	                    <DeviceIcon className="h-3 w-3 text-muted-foreground shrink-0" />
291	                    <span className="text-muted-foreground font-mono">
292	                      {format(new Date(s.started_at), 'dd/MM HH:mm')}
293	                    </span>
294	                    <span className="text-foreground">{formatDuration(duration)}</span>
295	                  </div>
296	                );
297	              })}
298	            </div>
299	          </ScrollArea>
300	        </CardContent>
301	      </Card>
302	
303	      {/* Recent Activity Timeline */}
304	      <Card className="rounded-xl border-border/50">
305	        <CardHeader className="pb-2 px-3 pt-3">
306	          <CardTitle className="text-xs font-semibold text-muted-foreground">
307	            Atividade Recente
308	          </CardTitle>
309	        </CardHeader>
310	        <CardContent className="px-3 pb-3">
311	          <ScrollArea className="h-[150px]">
312	            <div className="space-y-1">
313	              {detail.recentActivity.slice(0, 20).map((a: any, i: number) => (
314	                <div key={i} className="flex items-start gap-2 text-xs">
315	                  <span className="text-muted-foreground font-mono whitespace-nowrap">
316	                    {format(new Date(a.created_at), 'HH:mm:ss')}
317	                  </span>
318	                  <Badge variant="outline" className="text-[10px] px-1 shrink-0">
319	                    {a.event_type}
320	                  </Badge>
321	                  <span className="text-muted-foreground truncate">
322	                    {a.page_route || a.element_id || '-'}
323	                  </span>
324	                </div>
325	              ))}
326	            </div>
327	          </ScrollArea>
328	        </CardContent>
329	      </Card>
330	    </div>
331	  );
332	}
