1	import { useQuery } from '@tanstack/react-query';
2	import { supabase } from '@/integrations/supabase/client';
3	
4	const sb = supabase as any;
5	
6	export interface AdminUser {
7	  user_id: string;
8	  nome: string;
9	  username: string;
10	  ativo: boolean;
11	  role_id: number | null;
12	  role_name: string | null;
13	  role_display_name: string | null;
14	  sessionCount: number;
15	  lastSession: string | null;
16	  pageViews: number;
17	  totalMinutes: number;
18	  isOnline: boolean;
19	}
20	
21	export interface UserDetail {
22	  recentSessions: any[];
23	  recentActivity: any[];
24	  topPages: { route: string; count: number }[];
25	}
26	
27	export function useAdminUsers() {
28	  const users = useQuery({
29	    queryKey: ['admin', 'users-list'],
30	    queryFn: async () => {
31	      const { data: profiles } = await supabase
32	        .from('profiles')
33	        .select('user_id, nome, username, ativo, role_id, user_roles(name, display_name)')
34	        .eq('ativo', true)
35	        .order('nome');
36	
37	      // Session stats per user
38	      const { data: sessions } = await sb
39	        .from('user_sessions')
40	        .select('user_id, started_at, last_activity, ended_at, is_online');
41	
42	      // Activity stats per user
43	      const { data: activity } = await sb
44	        .from('user_activity_log')
45	        .select('user_id, event_type')
46	        .eq('event_type', 'page_view');
47	
48	      return (profiles || []).map((p: any) => {
49	        const userSessions = (sessions || []).filter((s: any) => s.user_id === p.user_id);
50	        const userActivity = (activity || []).filter((a: any) => a.user_id === p.user_id);
51	        const isOnline = userSessions.some(
52	          (s: any) =>
53	            s.is_online && new Date(s.last_activity).getTime() > Date.now() - 2 * 60 * 1000
54	        );
55	
56	        const totalMinutes = userSessions.reduce((sum: number, s: any) => {
57	          const end = s.ended_at || s.last_activity;
58	          return sum + (new Date(end).getTime() - new Date(s.started_at).getTime()) / 60000;
59	        }, 0);
60	
61	        const role = p.user_roles as { name: string; display_name: string } | null;
62	
63	        return {
64	          user_id: p.user_id,
65	          nome: p.nome,
66	          username: p.username,
67	          ativo: p.ativo,
68	          role_id: p.role_id,
69	          role_name: role?.name || null,
70	          role_display_name: role?.display_name || null,
71	          sessionCount: userSessions.length,
72	          lastSession:
73	            userSessions.length > 0
74	              ? userSessions.sort(
75	                  (a: any, b: any) =>
76	                    new Date(b.started_at).getTime() - new Date(a.started_at).getTime()
77	                )[0].started_at
78	              : null,
79	          pageViews: userActivity.length,
80	          totalMinutes: Math.round(totalMinutes),

