75	export default function Usuarios() {
76	  const { user, loading: authLoading, refreshProfile } = useAuth();
77	  const { isAdmin, refreshPermissions, canAdminPermissions } = usePermissions();
78	  const navigate = useNavigate();
79	  const telemetryAttrs = useTelemetryAttrs();
80	  const { trackSubmissionStart: trackRoleFormStart, trackSubmissionSuccess: trackRoleFormSuccess, trackSubmissionError: trackRoleFormError } = useFormTelemetry('role');
81	  const { trackSubmissionStart: trackEmployeeFormStart, trackSubmissionSuccess: trackEmployeeFormSuccess, trackSubmissionError: trackEmployeeFormError } = useFormTelemetry('usuario');
82	  const [employees, setEmployees] = useState<Employee[]>([]);
83	  const [roles, setRoles] = useState<Role[]>([]);
84	  const [stores, setStores] = useState<Store[]>([]);
85	  const [permissions, setPermissions] = useState<Permission[]>([]);
86	  const [rolePermissions, setRolePermissions] = useState<RolePermission[]>([]);
87	  const [loading, setLoading] = useState(true);
88	  const [editingEmployee, setEditingEmployee] = useState<string | null>(null);
89	  const [selectedRole, setSelectedRole] = useState<number | null>(null);
90	  const [selectedStore, setSelectedStore] = useState<number | null>(null);
91	  const [activeTab, setActiveTab] = useState('usuarios');
92	  const [selectedRoleForPermissions, setSelectedRoleForPermissions] = useState<
93	    number | null
94	  >(null);
95	  const [newRoleName, setNewRoleName] = useState<string>('');
96	  const [newRoleDisplayName, setNewRoleDisplayName] = useState<string>('');
97	  const [newRoleDescription, setNewRoleDescription] = useState<string>('');
98	  const [editingRoleId, setEditingRoleId] = useState<number | null>(null);
99	  const [editedRoleDisplayName, setEditedRoleDisplayName] =
100	    useState<string>('');
101	  const [editedRoleDescription, setEditedRoleDescription] =
102	    useState<string>('');
103	
104	  // Utilitário para verificar se um role corresponde a administrador pelo nome
105	  const isRoleAdminById = (roleId: number | null | undefined) => {
106	    if (!roleId) return false;
107	    const role = roles.find((r) => r.id === roleId);
